const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const icon=(key)=>`<svg class="icon" aria-hidden="true"><use href="#i-${key}"/></svg>`;
const storage={getItem(k){try{return window.localStorage.getItem(k)}catch{return null}},setItem(k,v){try{window.localStorage.setItem(k,v)}catch{}}};
const model={me:null,route:'feed',lang:'de',theme:storage.getItem('kn.theme')||'system',offset:0,activeThread:null,latest:null,previewMedia:null,adminTab:'media',poll:null,ws:null};
const words={
 de:{login:'Anmelden',join:'Jetzt starten',landing1:'Augenblicke werden',landing2:'Erinnerungen.',landingDesc:'Teile, was dir wichtig ist. Folge deinen Leuten, entdecke neue Ideen und bleib im Gespräch. Alles an einem Ort.',createAccount:'Konto erstellen',haveAccount:'Ich habe schon ein Konto',sharedMoments:'Mach den Moment besonders',heroFooter:'Echte Momente. Deine Community. Ohne Abo.',imprint:'Impressum',privacy:'Datenschutz',terms:'Nutzungsbedingungen',feed:'Startseite',explore:'Entdecken',search:'Suche',create:'Erstellen',official:'Kennely',messages:'Nachrichten',notifications:'Mitteilungen',profile:'Profil',settings:'Einstellungen',admin:'Team',support:'Support',saved:'Gespeichert',logout:'Abmelden',welcome:'Willkommen zurück',signup:'Dein neues Konto',email:'E-Mail-Adresse',password:'Passwort',name:'Anzeigename',username:'Nutzername',birthday:'Geburtsdatum',gender:'Geschlecht',woman:'Frau',man:'Mann',diverse:'Andere Identität',agree:'Ich stimme den Nutzungsbedingungen und der Datenschutzerklärung zu',imAdult:'Ich bestätige, dass ich mindestens 18 bin.',send:'Weiter',usernameUsed:'Nutzername existiert schon',usernameMin:'Mindestens 5 Zeichen, beginnend mit einem Buchstaben.',passwordMin:'Mindestens 10 Zeichen verwenden.',adultOnly:'Du musst mindestens 16 Jahre alt sein.',emailVerify:'Bitte bestätige deine E-Mail-Adresse.',noPosts:'Hier ist es noch ruhig.',noPostsDesc:'Sobald jemand etwas teilt, siehst du es hier.',newPost:'Neuer Beitrag',newStory:'Neue Story',writeCaption:'Was möchtest du teilen?',choosePhoto:'Foto auswählen',photoReview:'Fotos werden erst nach Freigabe durch das Team sichtbar.',publish:'Teilen',cancel:'Abbrechen',like:'Gefällt mir',comment:'Kommentieren',comments:'Kommentare',save:'Speichern',report:'Melden',block:'Blockieren',unblock:'Entblocken',blocked:'Blockierte Konten',blockConfirm:'Dieses Konto blockieren? Ihr seht eure Beiträge und Nachrichten dann nicht mehr.',follow:'Folgen',unfollow:'Gefolgt',followers:'Follower',following:'Gefolgt',posts:'Beiträge',editProfile:'Profil bearbeiten',bio:'Biografie',city:'Stadt',visibility:'Sichtbarkeit',public:'Öffentlich',followersOnly:'Nur Follower',addComment:'Kommentar schreiben',commentSend:'Kommentar senden',pending:'Wartet auf Freigabe',story:'Story',createStory:'Story teilen',textStory:'Text deiner Story',background:'Hintergrund',delete:'Löschen',deleteAsk:'Beitrag wirklich löschen?',yesDelete:'Ja, löschen',no:'Nein',profilePhoto:'Profilfoto (wird geprüft)',sendMessage:'Nachricht',messageRequest:'Nachrichtenanfrage. Antworten erst nach Annahme möglich.',accept:'Annehmen',request:'Anfrage',writeMessage:'Nachricht schreiben',noMessages:'Noch keine Unterhaltungen',preferences:'Deine Einstellungen',language:'Sprache',theme:'Design',light:'Hell',dark:'Dunkel',system:'System',saveSettings:'Einstellungen speichern',privacyExport:'Meine Daten herunterladen',logoutAll:'Auf allen Geräten abmelden',deleteAccount:'Konto löschen',deleteConfirm:'Konto endgültig löschen?',passwordConfirm:'Zur Bestätigung Passwort eingeben',appeal:'Gegen Moderation Einspruch einlegen',appealDesc:'Erkläre, warum du mit einer Moderationsentscheidung nicht einverstanden bist.',submit:'Absenden',team:'Teamverwaltung',reviewQueue:'Prüfwarteschlange',reports:'Meldungen',appeals:'Einsprüche',teamRoles:'Mitarbeiterrollen',searchUser:'Nutzer über Nutzernamen suchen',role:'Rolle',assign:'Zuweisen',remove:'Entfernen',approve:'Genehmigen',reject:'Ablehnen',reason:'Grund',details:'Details',moderationReason:'Begründung der Entscheidung',under18:'Möglicherweise unter 18',spam:'Spam',abuse:'Belästigung',hate:'Hassrede',nudity:'Nacktheit',copyright:'Urheberrecht',impersonation:'Identitätsmissbrauch',illegal:'Rechtswidriger Inhalt',other:'Andere',flag:'Inhalt melden',confirmReport:'Diese Meldung absenden?',reportSent:'Meldung wurde gesendet',notificationsEmpty:'Keine neuen Mitteilungen',readAll:'Alle als gelesen markieren',tickets:'Supportanfragen',newTicket:'Neue Supportanfrage',subject:'Betreff',message:'Nachricht',category:'Kategorie',reply:'Antworten',help:'Wie können wir dir helfen?',account:'Konto',safety:'Sicherheit',technical:'Technisches Problem',verification:'Verifizierung',otherCategory:'Sonstiges',saveChanges:'Änderungen speichern',close:'Schließen',copyLink:'Link kopieren',officialTitle:'Offizielle Kennely-News',officialSubtitle:'Beiträge vom offiziellen Kennely-Konto.',followingFeed:'Gefolgt',allFeed:'Für dich',refresh:'Aktualisieren',success:'Gespeichert',tryAgain:'Etwas ist schiefgelaufen',unavailable:'Nicht verfügbar',verified:'Verifiziert',ceo:'CEO',moderator:'Teammitglied',notPublished:'Dein Bild wird noch geprüft und ist nicht öffentlich.',resend:'Bestätigung erneut senden',noResults:'Keine Profile gefunden',searchPlaceholder:'Nach @Nutzername suchen',supportLabel:'Wir helfen dir gerne',storyExpire:'Storys verschwinden nach 24 Stunden.',noStory:'Keine aktuellen Storys',more:'Mehr laden',requestAccepted:'Anfrage angenommen',owner:'Owner',manager:'Manager',adminRole:'Admin',moderatorRole:'Moderator',supportRole:'Support',ownerHint:'Der CEO-Zugang kommt über die Owner-Rolle.',legalReminder:'Vor dem öffentlichen Start sind eine Rechtsprüfung und weitere Schutzmaßnahmen notwendig.'}
};
function tr(key){if(key==='imAdult')return 'Ich bin mindestens 16 Jahre alt.';if(key==='adultOnly')return 'Du musst mindestens 16 Jahre alt sein.';if(key==='under18')return 'Person möglicherweise unter 16';const extra={no:'Nein',reels:'Reels',privacy:'Datenschutz',help:'Wie können wir dir helfen?',legal:'Rechtliches'};return words.de[key]||extra[key]||key;}
const svg=(name)=>icon(name);
function badge(p){return p?.role||p?.staffRole||p?.official?`<span class="verified" title="${esc(p?.official?tr('verified'):tr('moderator'))}">${svg('check')}</span>`:'';}
function avatar(p,size=''){const img=p?.photoId||p?.photos?.[0];return `<span class="avatar ${size}">${img?`<img src="/api/photos/${encodeURIComponent(img)}" alt="" loading="lazy">`:icon('user')}</span>`;}
function showFormError(msg){if($('#modal')?.open){let e=$('#modal .modal-error');if(!e){e=document.createElement('p');e.className='modal-error';$('#modalBody').prepend(e)}e.textContent=msg;e.scrollIntoView({block:'nearest'});}else toast(msg);}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.tm);toast.tm=setTimeout(()=>e.classList.remove('show'),4000);}
async function api(path,opts={}){const res=await fetch('/api'+path,{credentials:'same-origin',...opts});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data;}
const post=(p,d)=>api(p,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});
const patch=(p,d)=>api(p,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(d)});
const del=p=>api(p,{method:'DELETE'});
const profileImg=id=>id?`/api/photos/${encodeURIComponent(id)}`:null;
const socialImg=id=>id?`/api/social/media/${encodeURIComponent(id)}`:null;
function dateTime(v){if(!v)return '';const v2=/^\d{4}-\d{2}-\d{2} /.test(v)?v.replace(' ','T')+'Z':v;try{return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium'}).format(new Date(v2));}catch{return '';}}
function formatCount(n){return Number(n||0).toLocaleString('de-DE');}
const ask=(title,desc,yes)=>new Promise(resolve=>{openModal(`<h2>${esc(title)}</h2><p>${esc(desc||'')}</p><div class="split-actions inline-buttons"><button class="button outlined" id="modalNo">Nein</button><button class="button primary" id="modalYes">${esc(yes||tr('submit'))}</button></div>`);$('#modalNo').onclick=()=>{closeModal();resolve(false)};$('#modalYes').onclick=()=>{closeModal();resolve(true)};});
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();$('#modalBody').innerHTML='';}
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function setLang(l,sync=true){model.lang='de';document.documentElement.lang=model.lang;storage.setItem('kn.locale',model.lang);document.querySelectorAll('[data-t]').forEach(e=>{e.textContent=tr(e.dataset.t)});if(model.me){shell();navigate(model.route)}if(sync&&model.me)patch('/settings',{locale:model.lang,chatLocale:model.lang,theme:model.theme}).catch(()=>{});}
function setTheme(t,sync=true){model.theme=['system','dark','light'].includes(t)?t:'system';document.documentElement.dataset.theme=model.theme;storage.setItem('kn.theme',model.theme);if(sync&&model.me)patch('/settings',{locale:model.lang,chatLocale:model.lang,theme:model.theme}).catch(()=>{});}
function navLinks(){const arr=[['feed','home'],['explore','compass'],['create','plus'],['messages','mail'],['notifications','bell'],['profile','user']];if(model.me?.role)arr.push(['admin','shield']);return arr;}
function shell(){const u=model.me||{};$('#nav').innerHTML=navLinks().map(([n,ico])=>`<button class="nav-item ${model.route===n?'active':''}" data-go="${n}">${icon(ico)}<span>${tr(n)}</span>${n==='notifications'?'<span class="number-badge" id="navBadge" hidden></span>':''}</button>`).join('');$('#mobileNav').innerHTML=['feed','explore','create','messages','profile'].map(n=>{const ico=navLinks().find(x=>x[0]===n)?.[1]||'home';return `<button class="nav-item ${model.route===n?'active':''}" data-go="${n}">${icon(ico)}<span>${tr(n)}</span></button>`}).join('');$('#identity').innerHTML=`${avatar(u,'small')}<div><strong>${esc(u.name||u.username||'')}</strong> ${badge(u)}<br><small>@${esc(u.username||'')} ${u.role==='owner'?'· CEO':''}</small></div>`;updateBadge();}
function mountUser(u){model.me=u;$('#guest').classList.add('hidden');$('#shell').classList.remove('hidden');shell();if(!u.emailVerified&&!['localhost','127.0.0.1'].includes(location.hostname)){display(`<div class="panel"><h2>${tr('emailVerify')}</h2><button class="button primary" id="resend">${tr('resend')}</button></div>`);$('#resend').onclick=()=>post('/auth/resend-verification',{}).then(()=>toast(tr('success'))).catch(e=>toast(e.message));return;}navigate('feed');connectLive();}
function mountGuest(){model.me=null;$('#shell').classList.add('hidden');$('#guest').classList.remove('hidden');disconnectLive();setLang(model.lang,false);}
function display(html){$('#content').innerHTML=html;}
function page(title,subtitle='',right=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${right}</div>`;}
const empty=(emoji,title,description)=>`<div class="empty"><span class="emoji">${emoji}</span><h3>${esc(title)}</h3><p>${esc(description||'')}</p></div>`;
// Netlify Functions laufen nur während der Anfrage. Keine dauerhaften WebSockets/SSE.
// Sichtbarkeitsabhängiges Polling: Chat alle 15 Sekunden, Badge jede Minute.
// Der Eingabetext bleibt beim Aktualisieren einer Unterhaltung erhalten.
async function refreshCurrentThread(){
 if(!model.me||model.route!=='messages'||!model.activeThread||document.hidden)return;
 const id=model.activeThread;
 const root=$('#messageScroll');
 if(!root)return;
 const result=await api('/social/dm/'+encodeURIComponent(id));
 if(model.activeThread!==id)return;
 const sig=result.messages.map(m=>m.id).join('|');
 if(sig===model.threadSignature)return;
 model.threadSignature=sig;
 const atEnd=root.scrollHeight-root.scrollTop-root.clientHeight<80;
 root.innerHTML=result.messages.map(m=>`<div class="bubble ${m.senderId===model.me.id?'mine':''}">${esc(m.body)}</div>`).join('');
 if(atEnd)root.scrollTop=root.scrollHeight;
}
function connectLive(){
 disconnectLive();
 model.pollTicks=0;model.pollBusy=false;
 model.poll=setInterval(async()=>{
   if(!model.me||document.hidden||model.pollBusy)return;
   model.pollBusy=true;
   try{
     model.pollTicks++;
     if(model.route==='messages'&&model.activeThread)await refreshCurrentThread();
     if(model.pollTicks%4===0){
       await updateBadge();
       if(model.route==='notifications')await renderNotifications();
     }
   }catch{}finally{model.pollBusy=false;}
 },15000);
}
function disconnectLive(){clearInterval(model.poll);model.poll=null;if(model.ws){model.ws.close();model.ws=null;}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&model.me){updateBadge();if(model.route==='messages'&&model.activeThread)refreshCurrentThread().catch(()=>{});}});
async function updateBadge(){if(!model.me)return;try{const r=await api('/unread'),n=Number(r.count)||0;for(const id of ['navBadge','mobileBadge']){const el=$('#'+id);if(el){el.hidden=n===0;el.textContent=n>99?'99+':String(n)}}}catch{}}
async function navigate(route,options={}){if(!options.pop){const paths={feed:'/home',explore:'/entdecken',messages:'/nachrichten',notifications:'/mitteilungen',profile:'/profil/'+(model.me?.id||''),saved:'/gespeichert',activity:'/aktivitaeten',settings:'/einstellungen',support:'/support',admin:'/team'};const next=paths[route];if(next&&location.pathname!==next)history.pushState({route},'',next);}if(route==='create'){showComposer();return;}model.route=route;model.activeThread=null;shell();$('#rightRail').innerHTML=rightRail();display('<div class="spinner"></div>');try{
  if(route==='feed')await renderFeed(false,!!options.following);
  else if(route==='explore')await renderExplore();
  
  
  else if(route==='saved')await renderSaved();
   else if(route==='activity')await renderActivity();
  
  else if(route==='messages')await renderMessages();
  else if(route==='notifications')await renderNotifications();
  else if(route==='profile')await renderProfile(model.me.id);
  else if(route==='settings')await renderSettings();
  else if(route==='admin')await renderAdmin();
  else if(route==='support')await renderSupport();
  else navigate('feed');
}catch(e){display(empty('⚠',tr('tryAgain'),e.message));}}
function rightRail(){const u=model.me;return `<div class="widget"><div class="mini-row">${avatar(u,'small')}<div><strong>@${esc(u.username||'')}</strong><small>${u.role==='owner'?'CEO':'Dein Profil'}</small></div><button class="tiny-btn" data-go="profile">Profil ansehen</button></div></div><div class="widget"><h3>Entdecke deine Leute</h3><p>Finde Personen über ihren Nutzernamen und folge ihnen.</p><button class="button outlined small" data-go="explore">Entdecken</button></div>`;}
function postCard(p){const name=p.name||p.username||'user',media=p.mediaId?(p.mediaMime?.startsWith('video/')?'':`<img class="post-photo" loading="lazy" alt="${esc(name)}" src="${socialImg(p.mediaId)}">`):'';return `<article class="post" data-post="${esc(p.id)}"><div class="post-top">${avatar(p)}<div class="post-name"><button class="name-button" data-profile="${esc(p.userId||p.id)}">${esc(name)} ${badge(p)}</button><small>@${esc(p.username)} · ${dateTime(p.createdAt)}</small></div><button class="icon-button post-menu" title="${tr('report')}" data-report="post:${esc(p.id)}">${icon('more')}</button></div>${media}<div class="post-actions"><button class="icon-button ${p.liked?'active':''}" data-like="${esc(p.id)}" title="${tr('like')}">${icon('heart')}</button><button class="icon-button" data-comments="${esc(p.id)}" title="${tr('comments')}">${icon('comment')}</button><button class="icon-button save ${p.saved?'active':''}" data-save="${esc(p.id)}" title="${tr('save')}">${icon('bookmark')}</button></div><div class="post-meta"><span class="likes-count">${formatCount(p.likes)}</span> ${tr('like').toLowerCase()}</div>${p.caption?`<div class="post-copy"><button class="name-button caption-author" data-profile="${esc(p.userId||p.id)}">${esc(p.username)}</button>${esc(p.caption)}</div>`:''}<button class="post-comment-link" data-comments="${esc(p.id)}">${formatCount(p.comments)} ${tr('comments').toLowerCase()}</button>${p.userId===model.me?.id?`<button class="post-comment-link" data-delete-post="${esc(p.id)}">${tr('delete')}</button>`:''}</article>`;}
function storyButton(s){return `<button class="story-button" data-story="${esc(s.id)}"><span class="story-ring">${avatar(s)}</span><span>${esc(s.username||s.name)}</span></button>`;}
async function renderFeed(explore=false,following=false){const [posts,story]=await Promise.all([api(`/social/${explore?'explore':'feed'}?offset=0${following?'&following=1':''}`),api('/social/stories')]);model.offset=posts.posts.length;model.latest=explore?'explore':following?'following':'feed';
 const newStory=`<button class="story-button" data-new-story><span class="story-ring own-story">${avatar(model.me)}<b class="story-plus">+</b></span><span>Deine Story</span></button>`;
 display(`${page(explore?'Entdecken':'Startseite','',`<button class="button outlined small" data-go="create">＋ Beitrag</button>`)}${!explore?`<div class="story-bar">${newStory}${story.stories.map(storyButton).join('')}</div><div class="filter-row"><button class="chip ${!following?'active':''}" data-filter="all">Für dich</button><button class="chip ${following?'active':''}" data-filter="following">Gefolgt</button></div>`:''}<div id="postStream">${posts.posts.length?posts.posts.map(postCard).join(''):empty('✧','Noch keine Beiträge','Hier erscheinen freigegebene Beiträge.')}</div>${posts.hasMore?`<div style="text-align:center"><button class="button outlined" data-more-posts>Weitere Beiträge</button></div>`:''}`);
}
async function renderExplore(){
  await renderFeed(true);
  const top=document.querySelector('#content .page-head');
  if(top){top.insertAdjacentHTML('afterend',`<section class="explore-search panel"><label class="field" for="searchInput">Personen suchen<input id="searchInput" class="search-input" type="search" placeholder="Nutzername suchen" autocomplete="off" maxlength="24"></label><div id="searchResults" class="search-results"></div></section>`);}
}
async function renderActivity(){const r=await api('/social/liked');model.latest='liked';model.offset=r.posts.length;display(`${page('Deine Aktivitäten','Beiträge, die dir gefallen')}<div id="postStream">${r.posts.length?r.posts.map(postCard).join(''):empty('♡','Noch keine Likes','Beiträge, die dir gefallen, findest du hier.')}</div>`);}
async function renderReels(){
 const res=await api('/social/reels');model.offset=res.posts.length;model.latest='reels';
 display(`${page('Reels','Videos von deiner Community',`<button class="button primary small" data-compose-reel>＋ Reel hochladen</button>`)}<div id="postStream" class="reels-stream">${res.posts.length?res.posts.map(postCard).join(''):empty('▣','Noch keine Reels','Neue Videos erscheinen hier nach der Prüfung.')}</div>${res.hasMore?`<button class="button outlined" data-more-posts>${tr('more')}</button>`:''}`);
}
async function renderOfficial(){const res=await api('/social/official');model.offset=res.posts.length;model.latest='official';display(`${page(tr('officialTitle'),tr('officialSubtitle'))}<div id="postStream">${res.posts.length?res.posts.map(postCard).join(''):empty('✧',tr('noPosts'),tr('officialSubtitle'))}</div>${res.hasMore?`<button class="button outlined" data-more-posts>${tr('more')}</button>`:''}`);}
async function renderSaved(){const res=await api('/social/saved');model.offset=res.posts.length;model.latest='saved';display(`${page(tr('saved'))}<div id="postStream">${res.posts.length?res.posts.map(postCard).join(''):empty('♡',tr('noPosts'),tr('noPostsDesc'))}</div>`);}
async function morePosts(){const base=model.latest==='following'?'/social/feed?following=1':model.latest==='feed'?'/social/feed':`/social/${model.latest}`;const res=await api(base+(base.includes('?')?'&':'?')+'offset='+model.offset);model.offset+=res.posts.length;$('#postStream')?.insertAdjacentHTML('beforeend',res.posts.map(postCard).join(''));if(!res.hasMore)$('[data-more-posts]')?.remove();}
async function renderSearch(){display(`${page(tr('search'))}<div class="panel"><label class="field">${tr('searchUser')}<input class="search-input" id="searchInput" type="search" minlength="2" maxlength="24" placeholder="${tr('searchPlaceholder')}" autofocus></label><div id="searchResults" class="search-results">${empty('⌕',tr('search'),tr('searchPlaceholder'))}</div></div>`);}
let searchTimer;async function runSearch(q){const node=$('#searchResults');if(!node)return;if(q.length<2){node.innerHTML='';return;}try{const r=await api('/members/search?q='+encodeURIComponent(q));if(!$('#searchResults'))return;node.innerHTML=r.profiles.length?r.profiles.map(p=>`<button class="search-row" data-profile="${esc(p.id)}">${avatar(p)}<div><strong>${esc(p.name)} ${badge(p)}</strong><small>@${esc(p.username||'')}</small></div><span class="suffix">↗</span></button>`).join(''):empty('⌕',tr('noResults'),'');}catch(e){node.innerHTML=esc(e.message)}}
async function renderProfile(id){if(location.pathname!=='/profil/'+id)history.replaceState({route:'profile'},'','/profil/'+encodeURIComponent(id));const r=await api('/social/profiles/'+encodeURIComponent(id)),p=r.profile,own=id===model.me.id;model.currentProfile=p;
 const posts=p.posts||[],buttons=own?`<button class="button outlined small" data-edit-profile>${tr('editProfile')}</button><button class="button outlined small" data-go="settings">☰ Menü</button>`:`<button class="button primary small" data-follow="${esc(id)}">${p.followingUser?tr('unfollow'):tr('follow')}</button><button class="button outlined small" data-message-user="${esc(id)}">${tr('sendMessage')}</button><button class="button outlined small" data-report="user:${esc(id)}">${tr('report')}</button><button class="button outlined small" data-block-user="${esc(id)}">${tr('block')}</button>`;
 display(`<div class="profile-top"><div class="avatar-edit-wrap">${avatar(p,'big')}${own?'<button class="avatar-upload-plus" data-upload-avatar aria-label="Profilbild hochladen">＋</button>':''}</div><div class="profile-title"><h1>${esc(p.username)} ${badge(p)}</h1><div class="split-actions">${buttons}</div><div class="profile-stats"><span><strong>${formatCount(posts.length)}</strong> ${tr('posts')}</span><span><strong>${formatCount(p.followers)}</strong> ${tr('followers')}</span><span><strong>${formatCount(p.following)}</strong> ${tr('following')}</span><span><strong>${formatCount(p.totalLikes||0)}</strong> Likes</span></div><strong>${esc(p.name)}</strong> ${p.role==='owner'?'<span class="tag ceo-tag">CEO</span>':p.role?'<span class="tag team-tag">Kennely Team</span>':''}<p>${esc(p.bio||'')}</p><span class="tiny">${esc(p.city||'')}</span></div></div>${own?`<div class="filter-row" style="margin-top:20px"><button class="button primary small" data-go="create">＋ ${tr('newPost')}</button><button class="button outlined small" data-new-story>${tr('newStory')}</button></div>`:''}<div class="profile-grid">${posts.map(x=>`<button data-open-post="${esc(x.id)}">${x.mediaId?(x.mediaMime?.startsWith('video/')?`<video src="${socialImg(x.mediaId)}" preload="none" muted playsinline></video><span class="reel-corner">▶</span>`:`<img loading="lazy" src="${socialImg(x.mediaId)}" alt="">`):`<span class="txt-tile">${esc(x.caption.slice(0,100))}</span>`}</button>`).join('')}</div>${!posts.length?empty('✧',tr('noPosts'),tr('noPostsDesc')):''}`);
}
async function openPost(id){const res=await api('/social/feed?offset=0');const p=res.posts.find(x=>x.id===id);if(p)openModal(postCard(p));else toast(tr('unavailable'));}
function showComposer(kind='post'){const story=kind==='story';model.previewMedia=null;openModal(`<h2>${story?tr('newStory'):tr('newPost')}</h2><p>${story?tr('storyExpire'):tr('photoReview')}</p><form id="composeForm" class="column"><label class="field">${story?tr('textStory'):tr('writeCaption')}<textarea name="text" maxlength="${story?320:1500}" placeholder="${story?tr('textStory'):tr('writeCaption')}"></textarea></label><label class="field"><span class="upload-icon">＋</span><span class="upload-label">Foto auswählen</span><input id="newPhoto" type="file" accept="image/png,image/jpeg,image/webp"><span class="field-hint">Fotos werden vor der Veröffentlichung geprüft und automatisch verkleinert.</span></label><div id="photoPreview"></div>${!story?`<label class="field">${tr('visibility')}<select name="visibility"><option value="public">${tr('public')}</option><option value="followers">${tr('followersOnly')}</option></select></label>`:`<label class="field">${tr('background')}<input type="color" name="background" value="#6436d8"></label>`}<button class="button primary" type="submit">${tr('publish')}</button></form>`);$('#composeForm').dataset.kind=kind;}
async function compressFile(file,maxBytes=640000){const source=await createImageBitmap(file);const max=1400;const factor=Math.min(1,max/Math.max(source.width,source.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.width*factor));canvas.height=Math.max(1,Math.round(source.height*factor));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);source.close?.();for(const quality of [.82,.70,.58,.46]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=maxBytes)return blob;}throw new Error('Photo is too large. Try a smaller picture.');}
async function createContent(form){const kind=form.dataset.kind,fd=new FormData(form),file=$('#newPhoto')?.files?.[0];let mediaId=null;if(file){const video=false;if(video)throw new Error('Nur Fotos sind erlaubt.');
  if(video&&file.size>18000000)throw new Error('Das Video darf maximal 18 MB groß sein.');
  const blob=video?file:await compressFile(file);const result=await api('/social/media?kind='+(kind==='reel'?'post':kind),{method:'POST',headers:{'content-type':video?file.type:'image/jpeg'},body:blob});mediaId=result.id;}
 const data=kind==='story'?{body:String(fd.get('text')||''),mediaId,background:String(fd.get('background')||'#6436d8')}:{caption:String(fd.get('text')||''),mediaId,visibility:String(fd.get('visibility')||'public')};const res=await post(`/social/${kind==='story'?'stories':'posts'}`,data);closeModal();toast(res.pendingReview?tr('notPublished'):tr('success'));navigate('feed');}
