// One delegated event pipeline: dynamic cards and mobile navigation remain usable.
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.hasAttribute('data-compose-reel')){showComposer('reel');return;}
 if(b.hasAttribute('data-daily-moment')){showComposer('post');const input=$('#composeForm textarea[name=text]');if(input)input.value='Mein Moment heute: ';return;}
 if(b.dataset.hideDm){if(!await ask('Unterhaltung entfernen?','Diese Unterhaltung verschwindet nur aus deiner eigenen Liste.','Ja, entfernen'))return;await post('/social/dm/'+encodeURIComponent(b.dataset.hideDm)+'/hide',{});model.activeThread=null;renderMessages();return;}
 if(b.dataset.reportDm){const id=b.dataset.reportDm;if(!await ask('Unterhaltung melden?','Die letzten 20 Nachrichten werden als Belege an die Moderation übermittelt.','Ja, melden'))return;await post('/social/dm/'+encodeURIComponent(id)+'/report',{reason:'abuse',details:'Die Unterhaltung soll durch das Kennely Team geprüft werden.'});toast('Deine Meldung wurde übermittelt.');return;}
 if(b.dataset.ticketStatus){const [id,status]=b.dataset.ticketStatus.split(':');if(!await ask('Supportfall als erledigt markieren?','Der Bearbeitungsstatus wird gespeichert.','Bestätigen'))return;await api('/support/'+id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status})});renderAdmin();return;}
 if(b.dataset.evidence){const reason=prompt('Warum musst du die Belege dieser Meldung einsehen?');if(!reason||reason.trim().length<12)return;const d=await api('/social/admin/conversation-evidence/'+b.dataset.evidence+'?reason='+encodeURIComponent(reason));openModal(`<h2>Gemeldete Chatnachrichten</h2><p>Nur die vom Nutzer übermittelten Belege. Der Zugriff wird protokolliert.</p>${d.evidence.map(m=>`<div class="notification"><strong>${esc(m.senderId)}</strong><p>${esc(m.body)}</p></div>`).join('')}`);return;}
 if(b.dataset.go){e.preventDefault();navigate(b.dataset.go);return;}
 if(b.dataset.guest){e.preventDefault();authModal(b.dataset.guest);return;}
 if(b.hasAttribute('data-change-password')){passwordChangeModal();return;}
 if(b.hasAttribute('data-forgot-password')){forgotPasswordModal();return;}
 if(b.dataset.profile){e.preventDefault();model.route='profile';shell();await renderProfile(b.dataset.profile);return;}
 if(b.dataset.filter){navigate('feed',{following:b.dataset.filter==='following'});return;}
 if(b.hasAttribute('data-new-story')){showComposer('story');return;}
 if(b.dataset.story){openStory(b.dataset.story);return;}
 if(b.dataset.like){const r=await post(`/social/posts/${b.dataset.like}/like`,{});b.classList.toggle('active',r.active);const parent=b.closest('.post'),count=parent?.querySelector('.likes-count');if(count)count.textContent=formatCount(Math.max(0,Number(count.textContent.replace(/[^\d]/g,''))+(r.active?1:-1)));return;}
 if(b.dataset.save){const r=await post(`/social/posts/${b.dataset.save}/save`,{});b.classList.toggle('active',r.active);toast(r.active?tr('success'):tr('remove'));return;}
 if(b.dataset.comments){openComments(b.dataset.comments);return;}
 if(b.dataset.report){const [type,id]=b.dataset.report.split(':');reportModal(type,id);return;}
 if(b.dataset.openPost){openPost(b.dataset.openPost);return;}
 if(b.dataset.deletePost){if(await ask(tr('deleteAsk'),'',tr('yesDelete'))){await del('/social/posts/'+b.dataset.deletePost);toast(tr('success'));navigate(model.route);}return;}
 if(b.dataset.blockUser){if(!await ask(tr('block'),tr('blockConfirm'),tr('block')))return;await post('/block',{targetId:b.dataset.blockUser});toast(tr('success'));navigate('feed');return;}
 if(b.dataset.unblock){if(!await ask(tr('unblock'),'',tr('unblock')))return;await post('/unblock',{targetId:b.dataset.unblock});renderSettings();return;}
 if(b.dataset.follow){const r=await post('/social/follow',{userId:b.dataset.follow});toast(r.following?tr('follow'):tr('unfollow'));renderProfile(b.dataset.follow);return;}
 if(b.dataset.messageUser){const r=await post('/social/dm/open',{userId:b.dataset.messageUser});await navigate('messages');await openThread(r.id,false);return;}
 if(b.dataset.thread){openThread(b.dataset.thread);return;}
 if(b.dataset.acceptThread){await post('/social/dm/'+encodeURIComponent(b.dataset.acceptThread)+'/accept',{});toast(tr('requestAccepted'));openThread(b.dataset.acceptThread);return;}
 if(b.hasAttribute('data-read-all')){await post('/notifications/read',{all:true});renderNotifications();updateBadge();return;}
 if(b.hasAttribute('data-edit-profile')){editProfile();return;}
 if(b.hasAttribute('data-upload-avatar')){uploadAvatar();return;}
 if(b.hasAttribute('data-more-posts')){morePosts();return;}
 if(b.hasAttribute('data-new-ticket')){newTicket();return;}
 if(b.dataset.ticket){openTicket(b.dataset.ticket);return;}
 if(b.dataset.adminTab){model.adminTab=b.dataset.adminTab;renderAdmin();return;}
 if(b.dataset.reviewContent){const [type,id,status]=b.dataset.reviewContent.split(':');openReview('content',id,status);$('#reviewForm').dataset.contentType=type;return;}
 if(b.dataset.forwardMedia){const mediaId=b.dataset.forwardMedia;const data=await api('/social/admin/staff');openModal(`<h2>Zur Prüfung weiterleiten</h2><form id="forwardMediaForm" data-id="${esc(mediaId)}"><label class="field">Mitarbeiter<select name="toStaffId" required>${data.staff.filter(x=>x.id!==model.me.id).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Deine Nachricht<textarea name="note" minlength="8" maxlength="600" placeholder="Ich brauche bei diesem Beitrag deine Meinung." required></textarea></label><button type="submit" class="button primary">Weiterleiten</button></form>`);return;}
 if(b.dataset.reviewMedia){const [mediaId,status]=b.dataset.reviewMedia.split(':');openReview('media',mediaId,status);return;}
 if(b.dataset.reviewReport){const [reportId,status]=b.dataset.reviewReport.split(':');openReview('report',reportId,status);return;}
 if(b.dataset.reviewAppeal){const [appealId,status]=b.dataset.reviewAppeal.split(':');openReview('appeal',appealId,status);return;}
 if(b.dataset.staffAction){const [userId,action]=b.dataset.staffAction.split(':');openReview('user',userId,action);return;}
 if(b.hasAttribute('data-export')){const r=await api('/account/export');const blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kennely-export.json';a.click();URL.revokeObjectURL(url);return;}
 if(b.hasAttribute('data-logout-all')){if(await ask(tr('logoutAll'),'')){await post('/account/logout-all',{});mountGuest()}return;}
 if(b.hasAttribute('data-delete-account')){if(!await ask(tr('deleteConfirm'),''))return;openModal(`<h2>${tr('deleteAccount')}</h2><form id="deleteForm"><label class="field">${tr('passwordConfirm')}<input name="password" type="password" required></label><button class="button danger" type="submit">${tr('yesDelete')}</button></form>`);return;}
 }catch(err){toast(err.message||tr('tryAgain'));}});

document.addEventListener('input',e=>{if(e.target.id==='searchInput'){clearTimeout(searchTimer);const val=e.target.value.trim().replace(/^@/,'');searchTimer=setTimeout(()=>runSearch(val),250);}
 if(e.target.id==='adminFind'){clearTimeout(searchTimer);const q=e.target.value.trim();searchTimer=setTimeout(async()=>{if(q.length<2)return;try{const data=await api('/admin/users?q='+encodeURIComponent(q));const root=$('#adminUsersResults');if(!root)return;root.innerHTML=data.users.map(u=>`<div class="admin-line"><div><strong>${esc(u.name)} ${badge({role:u.role})}</strong><p>${esc(u.email)} · ${u.banned?'Gesperrt':'Aktiv'}</p></div><div class="split-actions"><button class="button outlined small" data-staff-action="${esc(u.id)}:warning">Verwarnung</button><button class="button outlined small" data-staff-action="${esc(u.id)}:restrict">Einschränken</button><button class="button danger small" data-staff-action="${esc(u.id)}:${u.banned?'unban':'ban'}">${u.banned?'Entsperren':'Sperren'}</button></div></div>`).join('')||tr('noResults');}catch(e){toast(e.message)}},300);}
 if(e.target.id==='usernameField'){clearTimeout(searchTimer);const hint=$('#usernameHint'),name=e.target.value.trim().toLowerCase();if(!hint)return;if(!/^[a-z][a-z0-9._]{4,23}$/.test(name)){hint.textContent=tr('usernameMin');hint.className='field-error';return;}searchTimer=setTimeout(async()=>{try{const r=await api('/auth/username?name='+encodeURIComponent(name));if($('#usernameField')?.value.trim().toLowerCase()!==name)return;hint.textContent=r.available?'✓ @'+name:tr('usernameUsed');hint.className=r.available?'field-success':'field-error';}catch{}},400);}});

document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;const fd=new FormData(form);try{
 if(form.id==='reviewForm'){const kind=form.dataset.reviewKind,id=form.dataset.reviewId,status=form.dataset.reviewStatus,reason=String(fd.get('reason')||'');if(kind==='content')await post('/social/admin/content-review',{id,type:form.dataset.contentType,status,reason});if(kind==='media')await post('/social/admin/review',{mediaId:id,status,reason});if(kind==='report')await post('/social/admin/report',{reportId:id,status,note:reason,removeContent:fd.has('removeContent')});if(kind==='appeal')await post('/social/admin/appeal',{appealId:id,status});if(kind==='user')await post('/admin/moderate',{userId:id,action:status,reason,feature:fd.get('feature')||'chat',days:Math.max(1,Math.min(365,Number(fd.get('days')||7))),notifyEmail:fd.has('notifyEmail')});closeModal();toast(tr('success'));renderAdmin();}
 else if(form.id==='authForm'){const data={email:fd.get('email'),password:fd.get('password')};if(form.dataset.kind==='register'){const dob=fd.get('birthDate'),cut=cutoff();if(dob>cut)throw new Error(tr('adultOnly'));Object.assign(data,{name:fd.get('name'),username:fd.get('username'),birthDate:dob,gender:fd.get('gender'),city:'',adult:fd.has('adult'),terms:fd.has('terms')});}const r=await post('/auth/'+(form.dataset.kind==='register'?'register':'login'),data);closeModal();mountUser(r.user);}
 else if(form.id==='composeForm'){await createContent(form);}
 else if(form.id==='commentForm'){await post(`/social/posts/${form.dataset.id}/comments`,{body:fd.get('body')});await openComments(form.dataset.id);}
 else if(form.id==='reportForm'){const type=form.dataset.targetType,id=form.dataset.targetId;if(!await ask(tr('confirmReport'),tr('reason')))return;await post('/social/report',{type,id,reason:fd.get('reason'),details:fd.get('details')});closeModal();toast(tr('reportSent'));}
 else if(form.id==='sendMessageForm'){await post('/social/dm/'+encodeURIComponent(form.dataset.thread)+'/send',{body:fd.get('body')});openThread(form.dataset.thread,false);}
 else if(form.id==='settingsForm'){await patch('/settings',{locale:'de',theme:fd.get('theme'),chatLocale:'de',notifyMessages:fd.has('notifyMessages')});setTheme(fd.get('theme'),false);setLang('de',false);toast(tr('success'));}
 else if(form.id==='editProfileForm'){await patch('/profile',{name:fd.get('name'),bio:fd.get('bio'),city:fd.get('city'),gender:model.me.gender||'divers',lookingFor:'alle',intent:'offen',interests:model.me.interests||[],visible:true});model.me.name=String(fd.get('name'));model.me.bio=String(fd.get('bio'));model.me.city=String(fd.get('city'));closeModal();renderProfile(model.me.id);}
 else if(form.id==='passwordChangeForm'){await post('/account/change-password',{current:fd.get('current'),next:fd.get('next')});closeModal();toast('Dein Passwort wurde geändert.');}
 else if(form.id==='forgotPasswordForm'){await post('/auth/request-reset',{email:fd.get('email')});closeModal();toast('Falls du ein Konto hast, erhältst du einen Link.');}
 else if(form.id==='resetPasswordForm'){await post('/auth/reset',{token:fd.get('token'),password:fd.get('password')});closeModal();toast('Passwort geändert. Bitte melde dich an.');}
 else if(form.id==='avatarForm'){const file=fd.get('photo'),blob=await compressFile(file);await api('/photos',{method:'POST',headers:{'content-type':'image/jpeg'},body:blob});closeModal();toast(tr('notPublished'));}
 else if(form.id==='appealForm'){await post('/social/appeal',{reason:fd.get('reason')});toast(tr('success'));form.reset();}
 else if(form.id==='ticketForm'){await post('/support',{category:fd.get('category'),subject:fd.get('subject'),body:fd.get('body')});closeModal();navigate('support');}
 else if(form.id==='ticketReply'){await post('/support/'+form.dataset.id+'/reply',{body:fd.get('body')});openTicket(form.dataset.id);}
 else if(form.id==='forwardMediaForm'){await post('/social/admin/forward',{mediaId:form.dataset.id,toStaffId:fd.get('toStaffId'),note:fd.get('note')});closeModal();toast('An das Team weitergeleitet.');renderAdmin();}
 else if(form.id==='legalRequestForm'){await post('/legal-requests',{reference:fd.get('reference'),authority:fd.get('authority'),legalBasis:fd.get('legalBasis'),scope:fd.get('scope')});toast('Anfrage wurde dokumentiert.');renderAdmin();}
 else if(form.id==='teamForm'){if(model.me.role!=='owner')throw new Error('Nur für den CEO');const email=String(fd.get('email')||'').trim();const users=await api('/admin/users?q='+encodeURIComponent(email));const usr=users.users.find(x=>x.email.toLowerCase()===email.toLowerCase());if(!usr)throw new Error(tr('noResults'));if(!await ask(tr('assign'),email+' → '+fd.get('role')))return;await post('/admin/team',{userId:usr.id,role:fd.get('role')});toast(tr('success'));renderAdmin();}
 else if(form.id==='deleteForm'){await post('/account/delete',{password:fd.get('password'),confirm:'KONTO LÖSCHEN'});closeModal();mountGuest();}
 }catch(err){showFormError(err.message||tr('tryAgain'));}finally{if(submit&&submit.isConnected)submit.disabled=false;}});

// Kennely Deutschland: die Oberfläche bleibt vollständig deutsch.
window.addEventListener('popstate',()=>{if(!model.me)return;const path=location.pathname;const mapping={'/':'feed','/home':'feed','/entdecken':'explore','/nachrichten':'messages','/mitteilungen':'notifications','/gespeichert':'saved','/aktivitaeten':'activity','/einstellungen':'settings','/support':'support','/team':'admin'};if(path.startsWith('/profil/'))renderProfile(path.slice(8));else navigate(mapping[path]||'feed',{pop:true});});
(async()=>{setTheme(model.theme,false);setLang(model.lang,false);try{const r=await api('/me');if(r.user){try{const settings=await api('/settings');model.lang='de';if(settings.preferences?.theme)model.theme=settings.preferences.theme;setTheme(model.theme,false);setLang(model.lang,false);}catch{}mountUser(r.user)}else mountGuest();}catch{mountGuest();}})();

const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken&&/^[a-f0-9]{64}$/.test(resetToken))setTimeout(()=>{resetPasswordModal(resetToken);history.replaceState({},'',location.pathname)},350);
